extern float WAVE_camy;
extern float WAVETEX_DarkAlphaScale;
extern float WAVETEX_DarkAlphaOffset;
extern float WAVETEX_DarkHighAlphaScale;
extern float WAVETEX_DarkHighAlphaOffset;
extern float WAVETEX_DarkUnderAlphaScale;
extern float WAVETEX_DarkUnderAlphaOffset;
extern float lo_dark_limit;
extern float hi_dark_limit;

bool WAVETEX_CameraUnderwater(void);
void WAVERENDER_SetWaveDarkParams(float scale, float offset);

__asm__(".equ WAVE_camy, 0x00484524");
__asm__(".equ WAVETEX_DarkAlphaScale, 0x00484E20");
__asm__(".equ WAVETEX_DarkAlphaOffset, 0x00484E24");
__asm__(".equ WAVETEX_DarkHighAlphaScale, 0x00484E28");
__asm__(".equ WAVETEX_DarkHighAlphaOffset, 0x00484E2C");
__asm__(".equ WAVETEX_DarkUnderAlphaScale, 0x00484E30");
__asm__(".equ WAVETEX_DarkUnderAlphaOffset, 0x00484E34");
__asm__(".equ lo_dark_limit, 0x00484E90");
__asm__(".equ hi_dark_limit, 0x00484E94");
__asm__(".equ WAVETEX_CameraUnderwater__Fv, 0x0037E5C8");
__asm__(".equ WAVERENDER_SetWaveDarkParams__Fff, 0x001E7400");

void WAVETEX_SetCameraPos( )
{
	const float &y = WAVE_camy;
	if ( WAVETEX_CameraUnderwater() )
	{
		WAVERENDER_SetWaveDarkParams( WAVETEX_DarkUnderAlphaScale/128.0f, WAVETEX_DarkUnderAlphaOffset/128.0f );
	}
	else if ( y<=lo_dark_limit )
	{
		WAVERENDER_SetWaveDarkParams( WAVETEX_DarkAlphaScale/128.0f, WAVETEX_DarkAlphaOffset/128.0f );
	}
	else if ( y>=hi_dark_limit )
	{
		WAVERENDER_SetWaveDarkParams( WAVETEX_DarkHighAlphaScale/128.0f, WAVETEX_DarkHighAlphaOffset/128.0f );
	}
	else
	{
		float hi=(y-lo_dark_limit)/(hi_dark_limit-lo_dark_limit);
		float lo=1.0f-hi;
		WAVERENDER_SetWaveDarkParams( (lo*WAVETEX_DarkAlphaScale + hi*WAVETEX_DarkHighAlphaScale)/128.0f,
		                      (lo*WAVETEX_DarkAlphaOffset + hi*WAVETEX_DarkHighAlphaOffset)/128.0f);
	}
}
